    if spec and spec != 'all':
        sql += " AND dp.specialization = %s"
        params.append(spec)
    if search:
        sql += " AND (u.full_name LIKE %s OR dp.specialization LIKE %s)"
        s = f"%{search}%"
        params.extend([s, s])
    sql += " ORDER BY dp.rating DESC"
    return jsonify(DB.fetch_all(sql, params))

